 if (rtn != DDS_RETCODE_OK)
    {
        printf("dp delete contained entities failed\n");
 return -1;
    }

rtn = DDS_DomainParticipantFactory_delete_participant(factory, dp);
 if (rtn != DDS_RETCODE_OK)
    {
        printf("dpf delete dp failed\n");
 return -1;
    }
