int ZRDDSDemoModulesInitial()
{
 // 获取入口，并指明QoS配置
 DDS_DomainParticipantFactory* factory = DDS_Init(NULL, "non_rio");
 if (factory == NULL) { printf("DDS_DomainParticipantFactory_get_instance failed.\n"); return -1; }
 // 初始化使用udp的域参与者
