该用例展示了典型的发布流程。

```c
#include "DomainParticipantFactory.h"
#include "DomainParticipant.h"
#include "DefaultQos.h"
#include "Publisher.h"
#include "DataWriter.h"
#include "FooTypeSupport.h"
#include "FooDataWriter.h"
#include "Foo.h"
#include <stdio.h>
#include "ZRSleep.h"

int main()
{
 /*域*/
 DDS_DomainId_t domainId = 11;
 DDS_DomainParticipantFactory* factory = DDS_DomainParticipantFactory_get_instance();
 if (NULL == factory)
    {
        printf("get instance failed.\n");
 return -1;
    }
 /*域参与者*/
 DDS_DomainParticipant *participant = DDS_DomainParticipantFactory_create_participant(factory, domainId, &DOMAINPARTICIPANT_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == participant)
    {
        printf("create participant failed.\n");
 return -1;
    }
 /*注册类型*/
 const char* type_name = FooTypeSupport_get_type_name();
 if (NULL == type_name)
    {
        printf("get type name failed.\n");
 return -1;
    }
 DDS_ReturnCode_t rtn = FooTypeSupport_register_type(participant, type_name);
 if (rtn != DDS_RETCODE_OK)
    {
        printf("register type failed.\n");
 return -1;
    }
 /*主题*/
 DDS_Topic *topic = DDS_DomainParticipant_create_topic(participant, "example", type_name, &TOPIC_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == topic)
    {
        printf("create topic failed.\n");
 return -1;
    }
 /*发布端*/
 DDS_Publisher *publisher = DDS_DomainParticipant_create_publisher(participant, &PUBLISHER_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == publisher)
    {
        printf("create publisher failed.\n");
 return -1;
    }
 /*datawriter*/
 DDS_DataWriterQos datawriter_qos;
 DDS_Publisher_get_default_datawriter_qos(publisher, &datawriter_qos);
    datawriter_qos.history.depth = 5;
 DDS_DataWriter *writer = DDS_Publisher_create_datawriter(publisher, topic, &datawriter_qos, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == writer)
    {
        printf("create datawriter failed.\n");
 return -1;
    }
 FooDataWriter *_writer = (FooDataWriter*)(writer);
 /*data*/
 Foo data;
    FooInitialize(&data);
 DDS_InstanceHandle_t handle = FooDataWriter_register_instance(_writer, &data);
 while (true)
    {
 /*此处可以对data赋值*/
 FooDataWriter_write(_writer, &data, &handle);
        printf("send a data\n");
 ZRSleep(1000);
    }
 return 0;
}
```

详细描述

为方便用户直接传输缓冲区数据类型，ZRDDS提供内置的缓冲区类型，该类型与字符串类型的主要区别为，允许内容中含有/0。

```c
DDS_Bytes sample;
DDS_OctetSeq_initialize(&sample.value);
// 租借用户空间，其中buffer为缓冲区，length为缓冲区长度
DDS_OctetSeq_loan_contiguous(&sample.value, buffer, length, length);
```

```c
Bytes sample;
// 租借用户空间，其中buffer为缓冲区，length为缓冲区长度
sample.loan_contiguous(&sample.value, buffer, length, length);
```

该用例展示了典型的基于监听器的订阅流程。

```c
#include "DomainParticipantFactory.h"
#include "DomainParticipant.h"
#include "DefaultQos.h"
#include "Subscriber.h"
#include "DataReader.h"
#include "Topic.h"
#include "DataReaderListener.h"
#include "Foo.h"
#include "FooDataReader.h"
#include "FooTypeSupport.h"
#include <stdio.h>
#include <string.h>

void MyListener_on_data_available(DDS_DataReader *the_reader)
{
    printf("received data.\n");
 FooDataReader *_reader = (FooDataReader*)the_reader;
 FooSeq data_values;
 FooSeq_initialize(&data_values);
 DDS_SampleInfoSeq sample_infos;
    DDS_SampleInfoSeq_initialize(&sample_infos);
 if (NULL == the_reader)
    {
        printf("datareader error.\n");
 return;
    }
 FooDataReader_take(_reader, &data_values, &sample_infos, MAX_INT32_VALUE, DDS_ANY_SAMPLE_STATE, DDS_ANY_VIEW_STATE, DDS_ANY_INSTANCE_STATE);
 for (int i = 0; i < sample_infos._length; i++)
    {
        FooPrintData(FooSeq_get_reference(&data_values, i));
    }
 FooDataReader_return_loan(_reader, &data_values, &sample_infos);
 return;
}

int main()
{
 /*域*/
 DDS_DomainId_t domainId = 11;
 DDS_DomainParticipantFactory* factory = DDS_DomainParticipantFactory_get_instance();
 if (NULL == factory)
    {
        printf("get insance failed.\n");
 return -1;
    }
 /*域参与者*/
 DDS_DomainParticipant *participant = DDS_DomainParticipantFactory_create_participant(factory, domainId, &DOMAINPARTICIPANT_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == participant)
    {
        printf("create participant failed.\n");
 return -1;
    }
 /*注册类型*/
 const char* type_name = FooTypeSupport_get_type_name();
 if (NULL == type_name)
    {
        printf("get type name failed.\n");
 return -1;
    }
 DDS_ReturnCode_t ret = FooTypeSupport_register_type(participant, type_name);
 if (ret != DDS_RETCODE_OK)
    {
        printf("register type failed.\n");
 return -1;
    }
 /*主题*/
 DDS_Topic *topic = DDS_DomainParticipant_create_topic(participant, "example", type_name, &TOPIC_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == topic)
    {
        printf("get topic failed.\n");
 return -1;
    }
 /*订阅端*/
 DDS_Subscriber *subscriber = DDS_DomainParticipant_create_subscriber(participant, &SUBSCRIBER_QOS_DEFAULT, NULL, DDS_STATUS_MASK_NONE);
 if (NULL == subscriber)
    {
        printf("create suscriber failed.\n");
 return -1;
    }
 /*设置监听器*/
 DDS_DataReaderListener readerListener;
    memset(&readerListener, 0, sizeof(readerListener));
    readerListener.on_data_available = MyListener_on_data_available;
 /*datareader*/
 DDS_DataReaderQos datareader_qos;
 DDS_Subscriber_get_default_datareader_qos(subscriber, &datareader_qos);
    datareader_qos.history.depth = 5;
 DDS_DataReader *reader = DDS_Subscriber_create_datareader(subscriber, (DDS_TopicDescription*)topic, &datareader_qos, &readerListener, DDS_STATUS_MASK_ALL);
 if (NULL == reader)
    {
        printf("create datareader failed.\n");
 return -1;
    }
 FooDataReader *_reader = (FooDataReader*)(reader);
 while (true)
    {
 ZRSleep(1000);
    }
 return 0;
}
```

调试文件实例

```c
// 开启任意主题相关的调试日志（特别注意：此处为3个"_"）
debug_cmd 2 ZRDDS_ANY_LOG_TOPIC_NAME___
// 开启任务实体ID的调试日志，共32个0
debug_cmd 4 00000000000000000000000000000000
// 取消使能编号为100到200范围的调试日志（更改为"debug_cmd 0"表示使能）
debug_cmd 1 100 200
//收到报文时，更新其它域参与者的存活状态
debug_cmd 1 59 59
//周期性检查其它节点的存活状态
debug_cmd 1 61 62
//数据读者收到数据写者信息时，打印其地址
debug_cmd 1 175 176
//数据读者匹配到数据写者
debug_cmd 1 178 178
//数据写者匹配到数据读者
debug_cmd 1 197 197
//数据读者与数据写者解除匹配
debug_cmd 1 183 183
//数据写者与数据读者解除匹配
debug_cmd 1 196 196
//数据写者发送心跳的心跳范围
debug_cmd 1 791 791
//数据写者进入waitForAllAcked的状态
debug_cmd 1 890 890
//数据写者收到数据读者的ACKNACK消息
debug_cmd 1 1290 1290
//数据写者重发DATA
debug_cmd 1 1293 1293
//数据写者重发DATA_FRAG
debug_cmd 1 1313 1313
//数据写者在某些数据被ACKED后释放已经不存活的实例
debug_cmd 1 776 776
//数据读者收到数据写者的心跳，打印
debug_cmd 1 474 474
//数据读者将数据标为已被接收
debug_cmd 1 773 773
//收到报文，打印报文长度及来源端口
debug_cmd 1 275 275
//数据读者收到数据后通知用户
debug_cmd 1 466 466
//数据读者收到数据写者的心跳后，构建ACKNACK
debug_cmd 1 590 590
```
